    fn boundary_grid() {
        let p = P as u64;
        let v: Vec<u64> = vec![0, 1, 2, 3, 0xFFFF_FFFE, 0xFFFF_FFFF, 1 << 32, (1 << 32) + 1,
            p - 2, p - 1, p, p + 1, p + 2, u64::MAX - 2, u64::MAX - 1, u64::MAX,
            1 << 63, (1 << 63) - 1, (1 << 63) + 1, 0xFFFF_FFFF_0000_0000, 0x0000_0001_FFFF_FFFF,
