        let mut n = 0u64;
        for &a in &v { for &f in &v {
            let t = total(a, f);
            let mut bs: Vec<u64> = v.clone();
            if t <= u64::MAX as u128 { bs.push(t as u64); }
            if t >= 1 && t - 1 <= u64::MAX as u128 { bs.push((t - 1) as u64); }
            for &b in &bs { assert_eq!(authorize(b, a, f), policy(b, a, f), "b={} a={} f={}", b, a, f); n += 1; }
        }}
